// Template-generated speech and nonverbal expressions. EVERY line here is a fixed template chosen by a
// trigger that corresponds to a real event or need in the simulation. Nothing is generated by a language
// model and nothing here implies understanding or consciousness. Bubbles carry kind:'template'.
export const TEMPLATES = {
  hungry:      { emote: 'hungry', lines: ['Hungry…', 'Need berries.', 'My belly is empty.'] },
  starving:    { emote: 'distress', lines: ['So hungry… weak…', 'Please… food…'] },
  eat:         { emote: 'happy', lines: ['Yum.', 'Berries!', 'That helps.'] },
  food_gone:   { emote: 'sad', lines: ['Nothing left here.', 'Empty bush…'] },
  tired:       { emote: 'tired', lines: ['So sleepy.', 'Need rest.'] },
  rest:        { emote: 'tired', lines: ['Zzz…', 'Resting.'] },
  gather:      { emote: 'working', lines: ['Collecting.', 'Got some.'] },
  build_start: { emote: 'working', lines: ['A new home!', 'Let us build.'] },
  build_stage: { emote: 'happy', lines: ['Getting there.', 'One step done.'] },
  build_done:  { emote: 'happy', lines: ['Home built!', 'Shelter ready.'] },
  hurt:        { emote: 'distress', lines: ['Ouch!', 'That hurt.'] },
  fire:        { emote: 'scared', lines: ['Fire! Run!', 'Too hot!'] },
  storm:       { emote: 'scared', lines: ['Storm! Get inside.', 'Wind is rough.'] },
  flee:        { emote: 'scared', lines: ['Away!', 'Run!'] },
  friend_visitor: { emote: 'happy', lines: ['You again! Hello.', 'A friend is here.'] },
  wary_visitor:   { emote: 'scared', lines: ['Not you…', 'Stay back.'] },
  thanks:      { emote: 'happy', lines: ['Thank you for the food.', 'Kind visitor!'] },
  greet:       { emote: 'happy', lines: ['Hello.', 'Nice to see you.'] },
  bond:        { emote: 'love', lines: ['Stay close.', 'We are a pair now.'] },
  mate:        { emote: 'love', lines: ['A little one is coming.'] },
  born:        { emote: 'happy', lines: ['…!', 'Hello world.'] },
  grief:       { emote: 'sad', lines: ['I miss them.', 'It is quiet now.'] },
  lonely:      { emote: 'sad', lines: ['Anyone around?'] },
};

export function makeBubble(rng, trigger, tick, cause) {
  const t = TEMPLATES[trigger];
  if (!t) return null;
  const i = rng.int(t.lines.length);
  return { kind: 'template', trigger, tpl: `${trigger}#${i}`, text: t.lines[i], emote: t.emote, tick, until: tick + 40, cause: cause ?? trigger };
}
